    image_mask: bool = false,

    fn deinit(self: *PageImage, alloc: Allocator) void {
        alloc.free(self.name);
        if (self.shared_rgba) |shared| shared.release(alloc) else alloc.free(self.rgba);
        self.* = undefined;
    }
