        alloc.free(runs);
    }
    try std.testing.expectEqual(@as(usize, 1), runs.len);
    try std.testing.expectEqual(@as(u32, 2), runs[0].width);
    try std.testing.expectEqual(@as(u32, 1), runs[0].height);
    try std.testing.expect(runs[0].rgba[0] < 55);
