    const container_params = .{
        .width = @as(u32, 1),
        .height = @as(u32, 1),
        .components = @as(u8, 2),
        .bits_per_component = @as(u8, 8),
        .extras = image_lib.jpeg2000.box.Jp2WriteExtras{ .cdef = &channel_definitions },
